-- Year 3 Week 9 multiplication and Week 10 synthesis lesson corrections.
UPDATE lessons SET title='Multiplication Through Repeated Addition',data=json_patch(data,'{"seed_key":"s2-mat-y3-w09-l2","title":"Multiplication Through Repeated Addition","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":9,"lesson_number":2,"duration_minutes":60,"child_mission":"Understand multiplication through repeated addition, follow original models and complete a new independent task.","learning_intention":"We are learning to apply multiplication through repeated addition with clear reasoning.","success_criteria":["I can explain the topic with an example.","I can use a worked method.","I can practise with supporting feedback.","I can complete a new task independently.","I can check and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Main ideas","cards":[{"front":"Recognise equal groups","back":"Repeated addition works when each group has the same number of items."},{"front":"Turn addition into multiplication","back":"The first factor tells how many groups and the second tells how many in each group."},{"front":"Draw a supporting array","back":"Use equal rows to show both the grouping and total."},{"front":"Check unequal groups","back":"Different group sizes cannot be described by one equal-group multiplication without adjusting."}]}],"printable_resource":{"title":"Multiplication Through Repeated Addition","instructions":"Read the examples, practise, then complete the independent task.","passage":"Four trays each hold six muffins.","prompts":["What do the facts show?","Show a model step.","Complete your own task.","Explain a check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Recognise equal groups","explain":"**Learn:** Repeated addition works when each group has the same number of items.\n\n**Original context:** Four trays each hold six muffins.","example":"**Teacher model:** Four trays of six means 6+6+6+6=24.\n\n**Guided example:** Three packs of five pencils: 5+5+5=15, so 3×5=15. Two rows of eight: 8+8=16, so 2×8=16. Explain why 4+6=10 does not describe four groups of six.\n\n**CHECK:** Explain why this method is sound.","notice":"Repeated addition works when each group has the same number of items.","check":{"question":"4 groups of 6 total?","options":["10","18","24","28"],"correct_index":2,"explanation":"24. Four trays of six means 6+6+6+6=24."},"visual_before":[{"episode":{"title":"Learning Multiplication Through Repeated Addition","transcript":"Pip: Four trays of six muffins sounds like four plus six.\nJuno: Count the equal groups: six plus six plus six plus six.\nPip: That''s twenty-four, which is four times six.\nJuno: Pause and draw four rows of six to show why. Explain a specific reason for your choice.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Four trays of six muffins sounds like four plus six."},{"who":"juno","text":"Count the equal groups: six plus six plus six plus six."},{"who":"pip","text":"That''s twenty-four, which is four times six."},{"who":"juno","text":"Pause and draw four rows of six to show why. Explain a specific reason for your choice.","pause_after":true}]}]}}]},{"icon":"📚","title":"Turn addition into multiplication","explain":"**Learn:** The first factor tells how many groups and the second tells how many in each group.\n\n**Original context:** Four trays each hold six muffins.","example":"**Teacher model:** 4×6=24 represents four groups of six.\n\n**Guided example:** Three packs of five pencils: 5+5+5=15, so 3×5=15. Two rows of eight: 8+8=16, so 2×8=16. Explain why 4+6=10 does not describe four groups of six.\n\n**CHECK:** Explain why this method is sound.","notice":"The first factor tells how many groups and the second tells how many in each group.","check":{"question":"Repeated addition for 3×5?","options":["3+5","5+5+5","3+3+3","5+3+5"],"correct_index":1,"explanation":"5+5+5. 4×6=24 represents four groups of six."}},{"icon":"✏️","title":"Draw a supporting array","explain":"**Learn:** Use equal rows to show both the grouping and total.\n\n**Original context:** Four trays each hold six muffins.","example":"**Teacher model:** Draw four rows of six dots. Count by sixes: 6,12,18,24.\n\n**Guided example:** Three packs of five pencils: 5+5+5=15, so 3×5=15. Two rows of eight: 8+8=16, so 2×8=16. Explain why 4+6=10 does not describe four groups of six.\n\n**CHECK:** Explain why this method is sound.","notice":"Use equal rows to show both the grouping and total.","check":{"question":"2×8?","options":["10","14","16","18"],"correct_index":2,"explanation":"16. Draw four rows of six dots. Count by sixes: 6,12,18,24."}},{"icon":"✅","title":"Check unequal groups","explain":"**Learn:** Different group sizes cannot be described by one equal-group multiplication without adjusting.\n\n**Original context:** Four trays each hold six muffins.","example":"**Teacher model:** Trays with six, six, five and six total 23, not 4×6=24.\n\n**Guided example:** Three packs of five pencils: 5+5+5=15, so 3×5=15. Two rows of eight: 8+8=16, so 2×8=16. Explain why 4+6=10 does not describe four groups of six.\n\n**CHECK:** Explain why this method is sound.","notice":"Different group sizes cannot be described by one equal-group multiplication without adjusting.","check":{"question":"7×4?","options":["21","24","28","32"],"correct_index":2,"explanation":"28. Trays with six, six, five and six total 23, not 4×6=24."}}],"worked_example":"## Model the method\n\nFour trays each hold six muffins.\n\n**1. Recognise equal groups:** Four trays of six means 6+6+6+6=24.\n\n**2. Turn addition into multiplication:** 4×6=24 represents four groups of six.\n\n**3. Draw a supporting array:** Draw four rows of six dots. Count by sixes: 6,12,18,24.\n\n**4. Check unequal groups:** Trays with six, six, five and six total 23, not 4×6=24.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 175\"><rect width=\"570\" height=\"175\" rx=\"10\" fill=\"#f2f8f4\"/><text x=\"14\" y=\"30\" font-family=\"Arial\" font-size=\"18\">Multiplication Through Repeated Addition</text><rect x=\"9\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"16\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Recognise equal g</text><rect x=\"151\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"158\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Turn addition int</text><rect x=\"293\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"300\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Draw a supporting</text><rect x=\"435\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"442\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Check unequal gro</text></svg>","alt":"Four key stages for Multiplication Through Repeated Addition","caption":"Use the worked lesson examples with these stages."}],"guided_practice":"Three packs of five pencils: 5+5+5=15, so 3×5=15. Two rows of eight: 8+8=16, so 2×8=16. Explain why 4+6=10 does not describe four groups of six.","independent_task":"A school market packs seven bags with four apples each and five boxes with six pears each. Write repeated additions and multiplication equations for both, draw one matching array and calculate the combined fruit count. A damaged apple bag has only three apples: explain the new total and why 7×4 no longer describes those apple bags exactly.","response_prompt":"A school market packs seven bags with four apples each and five boxes with six pears each. Write repeated additions and multiplication equations for both, draw one matching array and calculate the combined fruit count. A damaged apple bag has only three apples: explain the new total and why 7×4 no longer describes those apple bags exactly.","quiz":[{"type":"multiple_choice","question":"4 groups of 6 total?","options":["10","18","24","28"],"correct_index":2,"explanation":"24. Four trays of six means 6+6+6+6=24."},{"type":"multiple_choice","question":"Repeated addition for 3×5?","options":["3+5","5+5+5","3+3+3","5+3+5"],"correct_index":1,"explanation":"5+5+5. Four trays of six means 6+6+6+6=24."},{"type":"multiple_choice","question":"2×8?","options":["10","14","16","18"],"correct_index":2,"explanation":"16. Four trays of six means 6+6+6+6=24."},{"type":"multiple_choice","question":"7×4?","options":["21","24","28","32"],"correct_index":2,"explanation":"28. Four trays of six means 6+6+6+6=24."},{"type":"multiple_choice","question":"5×6?","options":["25","30","35","40"],"correct_index":1,"explanation":"30. Four trays of six means 6+6+6+6=24."},{"type":"multiple_choice","question":"Combined 28 apples and 30 pears?","options":["48","58","68","78"],"correct_index":1,"explanation":"58. Four trays of six means 6+6+6+6=24."},{"type":"multiple_choice","question":"If one apple bag loses one, apples total?","options":["26","27","28","29"],"correct_index":1,"explanation":"27. Four trays of six means 6+6+6+6=24."},{"type":"multiple_choice","question":"Four groups 6,6,5,6 total?","options":["22","23","24","25"],"correct_index":1,"explanation":"23. Four trays of six means 6+6+6+6=24."},{"type":"short_answer","question":"Complete the independent multiplication through repeated addition task.","sample_answer":"Seven bags of four apples give 4+4+4+4+4+4+4=28 or 7×4=28; five boxes of six pears give 6+6+6+6+6=30 or 5×6=30; combined total 58.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."},{"type":"short_answer","question":"Explain an important check or limitation in multiplication through repeated addition.","sample_answer":"With one apple missing, the apples total 27 and fruit total 57. The seven apple bags no longer contain equal groups of four, so the unadjusted multiplication expression overcounts by one.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."}],"parent_notes":"Parent: Have the child independently attempt the challenge and explain their approach before using these answers.\n\nParent: Written answer model 1. Seven bags of four apples give 4+4+4+4+4+4+4=28 or 7×4=28; five boxes of six pears give 6+6+6+6+6=30 or 5×6=30; combined total 58.\n\nParent: Written answer model 2. With one apple missing, the apples total 27 and fruit total 57. The seven apple bags no longer contain equal groups of four, so the unadjusted multiplication expression overcounts by one.\n\nParent: Retain original learning evidence and check NESA mapping separately.","evidence_instructions":"Save guided practice, independent work, a correction and both written assessments.","offline_alternative":"Complete the exercises on paper and retain a scan, photo or typed answer.","extension":"Design a new multiplication through repeated addition example and demonstrate your checking method.","stage_hints":{"accept":["Review the Multiplication Through Repeated Addition prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach0":["Review the Recognise equal groups prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach1":["Review the Turn addition into multiplication prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach2":["Review the Draw a supporting array prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach3":["Review the Check unequal groups prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"learn":["Review the Multiplication Through Repeated Addition prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"guided":["Review the Multiplication Through Repeated Addition prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"write":["Review the Multiplication Through Repeated Addition prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"quiz":["Review the Multiplication Through Repeated Addition prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"submit":["Review the Multiplication Through Repeated Addition prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."]}}') WHERE seed_key='s2-mat-y3-w09-l2';
UPDATE lessons SET title='Multiplication Facts: Twos, Fives and Tens',data=json_patch(data,'{"seed_key":"s2-mat-y3-w09-l3","title":"Multiplication Facts: Twos, Fives and Tens","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":9,"lesson_number":3,"duration_minutes":60,"child_mission":"Understand multiplication facts: twos, fives and tens, follow original models and complete a new independent task.","learning_intention":"We are learning to apply multiplication facts: twos, fives and tens with clear reasoning.","success_criteria":["I can explain the topic with an example.","I can use a worked method.","I can practise with supporting feedback.","I can complete a new task independently.","I can check and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Main ideas","cards":[{"front":"Count equal groups of two","back":"The two times table counts pairs: each new pair adds two."},{"front":"Skip-count in fives","back":"Counting 5,10,15,20 builds the multiplication pattern for four groups of five."},{"front":"Use tens and place value","back":"Each group of ten adds one more ten to the total."},{"front":"Relate and check facts","back":"A ten group is two five groups. Draw arrays or use division and repeated addition to test claims."}]}],"printable_resource":{"title":"Multiplication Facts: Twos, Fives and Tens","instructions":"Read the examples, practise, then complete the independent task.","passage":"A classroom arranges six pairs of shoes, four groups of five pencils and seven bundles of ten craft sticks.","prompts":["What do the facts show?","Show a model step.","Complete your own task.","Explain a check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Count equal groups of two","explain":"**Learn:** The two times table counts pairs: each new pair adds two.\n\n**Original context:** A classroom arranges six pairs of shoes, four groups of five pencils and seven bundles of ten craft sticks.","example":"**Teacher model:** Six pairs make 2+2+2+2+2+2=12, so 6×2=12.\n\n**Guided example:** Find 8×2=16 by pairs; 9×5=45 by counting fives; 6×10=60 by counting tens. Check 5×2=10 and 2×5=10 with arrays. Spot the mistake ''7×5=30'': seven groups of five total 35.\n\n**CHECK:** Explain why this method is sound.","notice":"The two times table counts pairs: each new pair adds two.","check":{"question":"8×2?","options":["14","16","18","20"],"correct_index":1,"explanation":"16. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},"visual_before":[{"episode":{"title":"Learning Multiplication Facts: Twos, Fives and Tens","transcript":"Pip: I know pairs help me count by twos.\nJuno: And packs of five help you skip-count by fives.\nPip: For bundles of ten, I can use the tens place.\nJuno: Pause and tell me how many are in seven bundles of ten. Explain a specific reason for your choice.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"I know pairs help me count by twos."},{"who":"juno","text":"And packs of five help you skip-count by fives."},{"who":"pip","text":"For bundles of ten, I can use the tens place."},{"who":"juno","text":"Pause and tell me how many are in seven bundles of ten. Explain a specific reason for your choice.","pause_after":true}]}]}}]},{"icon":"📚","title":"Skip-count in fives","explain":"**Learn:** Counting 5,10,15,20 builds the multiplication pattern for four groups of five.\n\n**Original context:** A classroom arranges six pairs of shoes, four groups of five pencils and seven bundles of ten craft sticks.","example":"**Teacher model:** Four packs of five pencils total 4×5=20. The units digit ends in 0 or 5.\n\n**Guided example:** Find 8×2=16 by pairs; 9×5=45 by counting fives; 6×10=60 by counting tens. Check 5×2=10 and 2×5=10 with arrays. Spot the mistake ''7×5=30'': seven groups of five total 35.\n\n**CHECK:** Explain why this method is sound.","notice":"Counting 5,10,15,20 builds the multiplication pattern for four groups of five.","check":{"question":"9×5?","options":["40","45","50","55"],"correct_index":1,"explanation":"45. Four packs of five pencils total 4×5=20. The units digit ends in 0 or 5."}},{"icon":"✏️","title":"Use tens and place value","explain":"**Learn:** Each group of ten adds one more ten to the total.\n\n**Original context:** A classroom arranges six pairs of shoes, four groups of five pencils and seven bundles of ten craft sticks.","example":"**Teacher model:** Seven bundles of ten sticks equal 7×10=70.\n\n**Guided example:** Find 8×2=16 by pairs; 9×5=45 by counting fives; 6×10=60 by counting tens. Check 5×2=10 and 2×5=10 with arrays. Spot the mistake ''7×5=30'': seven groups of five total 35.\n\n**CHECK:** Explain why this method is sound.","notice":"Each group of ten adds one more ten to the total.","check":{"question":"6×10?","options":["50","60","70","80"],"correct_index":1,"explanation":"60. Seven bundles of ten sticks equal 7×10=70."}},{"icon":"✅","title":"Relate and check facts","explain":"**Learn:** A ten group is two five groups. Draw arrays or use division and repeated addition to test claims.\n\n**Original context:** A classroom arranges six pairs of shoes, four groups of five pencils and seven bundles of ten craft sticks.","example":"**Teacher model:** 3×10=30; 6×5=30. Two different equal-group descriptions have the same total.\n\n**Guided example:** Find 8×2=16 by pairs; 9×5=45 by counting fives; 6×10=60 by counting tens. Check 5×2=10 and 2×5=10 with arrays. Spot the mistake ''7×5=30'': seven groups of five total 35.\n\n**CHECK:** Explain why this method is sound.","notice":"A ten group is two five groups. Draw arrays or use division and repeated addition to test claims.","check":{"question":"7×5?","options":["30","35","40","45"],"correct_index":1,"explanation":"35. 3×10=30; 6×5=30. Two different equal-group descriptions have the same total."}}],"worked_example":"## Model the method\n\nA classroom arranges six pairs of shoes, four groups of five pencils and seven bundles of ten craft sticks.\n\n**1. Count equal groups of two:** Six pairs make 2+2+2+2+2+2=12, so 6×2=12.\n\n**2. Skip-count in fives:** Four packs of five pencils total 4×5=20. The units digit ends in 0 or 5.\n\n**3. Use tens and place value:** Seven bundles of ten sticks equal 7×10=70.\n\n**4. Relate and check facts:** 3×10=30; 6×5=30. Two different equal-group descriptions have the same total.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 175\"><rect width=\"570\" height=\"175\" rx=\"10\" fill=\"#f2f8f4\"/><text x=\"14\" y=\"30\" font-family=\"Arial\" font-size=\"18\">Multiplication Facts: Twos, Fives and Tens</text><rect x=\"9\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"16\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Count equal group</text><rect x=\"151\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"158\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Skip-count in fiv</text><rect x=\"293\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"300\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Use tens and plac</text><rect x=\"435\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"442\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Relate and check </text></svg>","alt":"Four key stages for Multiplication Facts: Twos, Fives and Tens","caption":"Use the worked lesson examples with these stages."}],"guided_practice":"Find 8×2=16 by pairs; 9×5=45 by counting fives; 6×10=60 by counting tens. Check 5×2=10 and 2×5=10 with arrays. Spot the mistake ''7×5=30'': seven groups of five total 35.","independent_task":"Create a mini-fair inventory using 9 pairs of gloves, 6 packs of five stickers and 8 packets of ten buttons. Calculate all three totals and their combined quantity, show one skip-count sequence for each type, and explain why 5×10 and 10×5 produce equal totals. Correct the statement ''9×5=40''.","response_prompt":"Create a mini-fair inventory using 9 pairs of gloves, 6 packs of five stickers and 8 packets of ten buttons. Calculate all three totals and their combined quantity, show one skip-count sequence for each type, and explain why 5×10 and 10×5 produce equal totals. Correct the statement ''9×5=40''.","quiz":[{"type":"multiple_choice","question":"8×2?","options":["14","16","18","20"],"correct_index":1,"explanation":"16. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"multiple_choice","question":"9×5?","options":["40","45","50","55"],"correct_index":1,"explanation":"45. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"multiple_choice","question":"6×10?","options":["50","60","70","80"],"correct_index":1,"explanation":"60. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"multiple_choice","question":"7×5?","options":["30","35","40","45"],"correct_index":1,"explanation":"35. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"multiple_choice","question":"9×2?","options":["16","18","20","22"],"correct_index":1,"explanation":"18. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"multiple_choice","question":"6×5?","options":["25","30","35","40"],"correct_index":1,"explanation":"30. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"multiple_choice","question":"8×10?","options":["70","80","90","100"],"correct_index":1,"explanation":"80. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"multiple_choice","question":"Total 18+30+80?","options":["118","128","138","148"],"correct_index":1,"explanation":"128. Six pairs make 2+2+2+2+2+2=12, so 6×2=12."},{"type":"short_answer","question":"Complete the independent multiplication facts: twos, fives and tens task.","sample_answer":"9×2=18 gloves, 6×5=30 stickers and 8×10=80 buttons. All together 18+30+80=128 items. Skip-count gloves 2,4,6,8,10,12,14,16,18; stickers 5,10,15,20,25,30; buttons 10,20,30,40,50,60,70,80.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."},{"type":"short_answer","question":"Explain an important check or limitation in multiplication facts: twos, fives and tens.","sample_answer":"5×10=50 and 10×5=50 because five groups of ten and ten groups of five contain the same total. Nine groups of five are 45, not 40.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."}],"parent_notes":"Parent: Have the child independently attempt the challenge and explain their approach before using these answers.\n\nParent: Written answer model 1. 9×2=18 gloves, 6×5=30 stickers and 8×10=80 buttons. All together 18+30+80=128 items. Skip-count gloves 2,4,6,8,10,12,14,16,18; stickers 5,10,15,20,25,30; buttons 10,20,30,40,50,60,70,80.\n\nParent: Written answer model 2. 5×10=50 and 10×5=50 because five groups of ten and ten groups of five contain the same total. Nine groups of five are 45, not 40.\n\nParent: Retain original learning evidence and check NESA mapping separately.","evidence_instructions":"Save guided practice, independent work, a correction and both written assessments.","offline_alternative":"Complete the exercises on paper and retain a scan, photo or typed answer.","extension":"Design a new multiplication facts: twos, fives and tens example and demonstrate your checking method.","stage_hints":{"accept":["Review the Multiplication Facts: Twos, Fives and Tens prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach0":["Review the Count equal groups of two prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach1":["Review the Skip-count in fives prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach2":["Review the Use tens and place value prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach3":["Review the Relate and check facts prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"learn":["Review the Multiplication Facts: Twos, Fives and Tens prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"guided":["Review the Multiplication Facts: Twos, Fives and Tens prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"write":["Review the Multiplication Facts: Twos, Fives and Tens prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"quiz":["Review the Multiplication Facts: Twos, Fives and Tens prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"submit":["Review the Multiplication Facts: Twos, Fives and Tens prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."]}}') WHERE seed_key='s2-mat-y3-w09-l3';
UPDATE lessons SET title='Times Table Fluency: Show Your Strategy',data=json_patch(data,'{"seed_key":"s2-mat-y3-w09-l4","title":"Times Table Fluency: Show Your Strategy","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":9,"lesson_number":4,"duration_minutes":60,"child_mission":"Understand times table fluency: show your strategy, follow original models and complete a new independent task.","learning_intention":"We are learning to apply times table fluency: show your strategy with clear reasoning.","success_criteria":["I can explain the topic with an example.","I can use a worked method.","I can practise with supporting feedback.","I can complete a new task independently.","I can check and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Main ideas","cards":[{"front":"Use doubling for twos","back":"Multiplying by two doubles a quantity."},{"front":"Build fives with skip-counting","back":"Each group of five adds another five; a multiple of five ends in five or zero."},{"front":"Use tens as place-value groups","back":"Multiplying a whole number by ten counts tens, not a random digit trick."},{"front":"Explain and verify facts","back":"An array, reversed factors or repeated addition can show why a product is correct."}]}],"printable_resource":{"title":"Times Table Fluency: Show Your Strategy","instructions":"Read the examples, practise, then complete the independent task.","passage":"A practice card asks for 8×2, 7×5, 9×10 and 6×5.","prompts":["What do the facts show?","Show a model step.","Complete your own task.","Explain a check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Use doubling for twos","explain":"**Learn:** Multiplying by two doubles a quantity.\n\n**Original context:** A practice card asks for 8×2, 7×5, 9×10 and 6×5.","example":"**Teacher model:** 8×2=8+8=16. Check by eight pairs of two dots.\n\n**Guided example:** Solve 3×2=6, 8×5=40, 4×10=40 and 9×2=18, naming a strategy for each. Explain why 8×5=40 and not 35 by eight groups of five, or five groups of eight.\n\n**CHECK:** Explain why this method is sound.","notice":"Multiplying by two doubles a quantity.","check":{"question":"8×2?","options":["14","16","18","20"],"correct_index":1,"explanation":"16. 8×2=8+8=16. Check by eight pairs of two dots."},"visual_before":[{"episode":{"title":"Learning Times Table Fluency: Show Your Strategy","transcript":"Pip: Do I have to answer every multiplication fact instantly?\nJuno: Accuracy and a strategy come first. Fluency grows with practice.\nPip: I can double for twos and skip-count for fives and tens.\nJuno: Pause and show me how seven groups of five reach thirty-five.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Do I have to answer every multiplication fact instantly?"},{"who":"juno","text":"Accuracy and a strategy come first. Fluency grows with practice."},{"who":"pip","text":"I can double for twos and skip-count for fives and tens."},{"who":"juno","text":"Pause and show me how seven groups of five reach thirty-five.","pause_after":true}]}]}}]},{"icon":"📚","title":"Build fives with skip-counting","explain":"**Learn:** Each group of five adds another five; a multiple of five ends in five or zero.\n\n**Original context:** A practice card asks for 8×2, 7×5, 9×10 and 6×5.","example":"**Teacher model:** 7×5=35, from 5,10,15,20,25,30,35.\n\n**Guided example:** Solve 3×2=6, 8×5=40, 4×10=40 and 9×2=18, naming a strategy for each. Explain why 8×5=40 and not 35 by eight groups of five, or five groups of eight.\n\n**CHECK:** Explain why this method is sound.","notice":"Each group of five adds another five; a multiple of five ends in five or zero.","check":{"question":"7×5?","options":["30","35","40","45"],"correct_index":1,"explanation":"35. 7×5=35, from 5,10,15,20,25,30,35."}},{"icon":"✏️","title":"Use tens as place-value groups","explain":"**Learn:** Multiplying a whole number by ten counts tens, not a random digit trick.\n\n**Original context:** A practice card asks for 8×2, 7×5, 9×10 and 6×5.","example":"**Teacher model:** 9×10=90: nine groups each holding ten.\n\n**Guided example:** Solve 3×2=6, 8×5=40, 4×10=40 and 9×2=18, naming a strategy for each. Explain why 8×5=40 and not 35 by eight groups of five, or five groups of eight.\n\n**CHECK:** Explain why this method is sound.","notice":"Multiplying a whole number by ten counts tens, not a random digit trick.","check":{"question":"9×10?","options":["80","90","100","110"],"correct_index":1,"explanation":"90. 9×10=90: nine groups each holding ten."}},{"icon":"✅","title":"Explain and verify facts","explain":"**Learn:** An array, reversed factors or repeated addition can show why a product is correct.\n\n**Original context:** A practice card asks for 8×2, 7×5, 9×10 and 6×5.","example":"**Teacher model:** 6×5=30 and 5×6=30; both represent thirty objects arranged differently.\n\n**Guided example:** Solve 3×2=6, 8×5=40, 4×10=40 and 9×2=18, naming a strategy for each. Explain why 8×5=40 and not 35 by eight groups of five, or five groups of eight.\n\n**CHECK:** Explain why this method is sound.","notice":"An array, reversed factors or repeated addition can show why a product is correct.","check":{"question":"6×5?","options":["25","30","35","40"],"correct_index":1,"explanation":"30. 6×5=30 and 5×6=30; both represent thirty objects arranged differently."}}],"worked_example":"## Model the method\n\nA practice card asks for 8×2, 7×5, 9×10 and 6×5.\n\n**1. Use doubling for twos:** 8×2=8+8=16. Check by eight pairs of two dots.\n\n**2. Build fives with skip-counting:** 7×5=35, from 5,10,15,20,25,30,35.\n\n**3. Use tens as place-value groups:** 9×10=90: nine groups each holding ten.\n\n**4. Explain and verify facts:** 6×5=30 and 5×6=30; both represent thirty objects arranged differently.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 175\"><rect width=\"570\" height=\"175\" rx=\"10\" fill=\"#f2f8f4\"/><text x=\"14\" y=\"30\" font-family=\"Arial\" font-size=\"18\">Times Table Fluency: Show Your Strategy</text><rect x=\"9\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"16\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Use doubling for </text><rect x=\"151\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"158\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Build fives with </text><rect x=\"293\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"300\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Use tens as place</text><rect x=\"435\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"442\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Explain and verif</text></svg>","alt":"Four key stages for Times Table Fluency: Show Your Strategy","caption":"Use the worked lesson examples with these stages."}],"guided_practice":"Solve 3×2=6, 8×5=40, 4×10=40 and 9×2=18, naming a strategy for each. Explain why 8×5=40 and not 35 by eight groups of five, or five groups of eight.","independent_task":"Complete 7×2, 6×5, 9×2, 8×10, 5×5, 4×2, 7×10 and 3×5. For at least five, write a repeated-addition, double or skip-count justification. Create a four-question mini-quiz for a family member including a fair explanation of every correct answer. Correct ''8×5=35''.","response_prompt":"Complete 7×2, 6×5, 9×2, 8×10, 5×5, 4×2, 7×10 and 3×5. For at least five, write a repeated-addition, double or skip-count justification. Create a four-question mini-quiz for a family member including a fair explanation of every correct answer. Correct ''8×5=35''.","quiz":[{"type":"multiple_choice","question":"8×2?","options":["14","16","18","20"],"correct_index":1,"explanation":"16. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"multiple_choice","question":"7×5?","options":["30","35","40","45"],"correct_index":1,"explanation":"35. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"multiple_choice","question":"9×10?","options":["80","90","100","110"],"correct_index":1,"explanation":"90. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"multiple_choice","question":"6×5?","options":["25","30","35","40"],"correct_index":1,"explanation":"30. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"multiple_choice","question":"7×2?","options":["12","14","16","18"],"correct_index":1,"explanation":"14. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"multiple_choice","question":"8×10?","options":["70","80","90","100"],"correct_index":1,"explanation":"80. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"multiple_choice","question":"5×5?","options":["20","25","30","35"],"correct_index":1,"explanation":"25. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"multiple_choice","question":"3×5?","options":["10","15","20","25"],"correct_index":1,"explanation":"15. 8×2=8+8=16. Check by eight pairs of two dots."},{"type":"short_answer","question":"Complete the independent times table fluency: show your strategy task.","sample_answer":"7×2=14, 6×5=30, 9×2=18, 8×10=80, 5×5=25, 4×2=8, 7×10=70 and 3×5=15. Five example checks include 7+7=14, 5+5+5+5+5+5=30 and 8 tens=80.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."},{"type":"short_answer","question":"Explain an important check or limitation in times table fluency: show your strategy.","sample_answer":"8×5=40, not 35. Skip-count eight fives: 5,10,15,20,25,30,35,40. A sample quiz might ask 2×6, 5×4, 10×7 and 5×3, with answers 12,20,70,15 and array or repeated-addition reasons.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."}],"parent_notes":"Parent: Have the child independently attempt the challenge and explain their approach before using these answers.\n\nParent: Written answer model 1. 7×2=14, 6×5=30, 9×2=18, 8×10=80, 5×5=25, 4×2=8, 7×10=70 and 3×5=15. Five example checks include 7+7=14, 5+5+5+5+5+5=30 and 8 tens=80.\n\nParent: Written answer model 2. 8×5=40, not 35. Skip-count eight fives: 5,10,15,20,25,30,35,40. A sample quiz might ask 2×6, 5×4, 10×7 and 5×3, with answers 12,20,70,15 and array or repeated-addition reasons.\n\nParent: Retain original learning evidence and check NESA mapping separately.","evidence_instructions":"Save guided practice, independent work, a correction and both written assessments.","offline_alternative":"Complete the exercises on paper and retain a scan, photo or typed answer.","extension":"Design a new times table fluency: show your strategy example and demonstrate your checking method.","stage_hints":{"accept":["Review the Times Table Fluency: Show Your Strategy prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach0":["Review the Use doubling for twos prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach1":["Review the Build fives with skip-counting prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach2":["Review the Use tens as place-value groups prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach3":["Review the Explain and verify facts prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"learn":["Review the Times Table Fluency: Show Your Strategy prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"guided":["Review the Times Table Fluency: Show Your Strategy prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"write":["Review the Times Table Fluency: Show Your Strategy prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"quiz":["Review the Times Table Fluency: Show Your Strategy prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"submit":["Review the Times Table Fluency: Show Your Strategy prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."]}}') WHERE seed_key='s2-mat-y3-w09-l4';
UPDATE lessons SET title='Two Texts, One Explanation: Synthesise Information',data=json_patch(data,'{"seed_key":"s2-eng-y3-w10-l1","title":"Two Texts, One Explanation: Synthesise Information","stage":"Stage 2","learning_area":"English","year_level":3,"week":10,"lesson_number":1,"duration_minutes":60,"child_mission":"Understand two texts, one explanation: synthesise information, follow original models and complete a new independent task.","learning_intention":"We are learning to apply two texts, one explanation: synthesise information with clear reasoning.","success_criteria":["I can explain the topic with an example.","I can use a worked method.","I can practise with supporting feedback.","I can complete a new task independently.","I can check and explain one correction."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Main ideas","cards":[{"front":"Identify each text''s main idea","back":"Before combining sources, state what each contributes without mixing or changing its meaning."},{"front":"Find a shared idea","back":"Synthesis connects information from more than one source into a fuller understanding. A shared topic is not enough: identify the relationship."},{"front":"Combine facts in your own words","back":"Use a sentence that accurately draws on both texts without copying whole passages or claiming more than they say."},{"front":"Note limits and source contributions","back":"Distinguish what is supported by either text from overgeneralisations. Explain which source supports each fact."}]}],"printable_resource":{"title":"Two Texts, One Explanation: Synthesise Information","instructions":"Read the examples, practise, then complete the independent task.","passage":"Text A: ''Native bees visit flowers to gather nectar and pollen. Pollen may travel between flowers on their bodies.'' Text B: ''Many flowering plants can form seeds after pollen reaches the appropriate part of a flower. Some animals, including bees, can carry pollen.''","prompts":["What do the facts show?","Show a model step.","Complete your own task.","Explain a check."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Identify each text''s main idea","explain":"**Learn:** Before combining sources, state what each contributes without mixing or changing its meaning.\n\n**Original context:** Text A: ''Native bees visit flowers to gather nectar and pollen. Pollen may travel between flowers on their bodies.'' Text B: ''Many flowering plants can form seeds after pollen reaches the appropriate part of a flower. Some animals, including bees, can carry pollen.''","example":"**Teacher model:** Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds.\n\n**Guided example:** **Read two mini-texts.** Text A: ''Trees provide branches where some birds build nests.'' Text B: ''Bird nests can protect eggs and young from some weather conditions.'' State both main ideas, their shared idea (bird nests), and create a synthesis: ''Some birds build nests in trees, where the nests can shelter eggs and young.'' Explain why neither text claims every nest is in a tree.\n\n**CHECK:** Explain why this method is sound.","notice":"Before combining sources, state what each contributes without mixing or changing its meaning.","check":{"question":"What does Text A describe?","options":["Bees moving pollen as they visit flowers","All plant seeds are made by bees","Only birds pollinate","Every flower grows underwater"],"correct_index":0,"explanation":"Bees moving pollen as they visit flowers. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},"visual_before":[{"episode":{"title":"Learning Two Texts, One Explanation: Synthesise Information","transcript":"Pip: One text says bees move pollen, and another says pollen can help seeds form.\nJuno: Put the two ideas together without changing what either source claims.\nPip: Bees can carry pollen between flowers, helping some plants produce seeds.\nJuno: Good. Pause and name which text supports each part of your explanation.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"One text says bees move pollen, and another says pollen can help seeds form."},{"who":"juno","text":"Put the two ideas together without changing what either source claims."},{"who":"pip","text":"Bees can carry pollen between flowers, helping some plants produce seeds."},{"who":"juno","text":"Good. Pause and name which text supports each part of your explanation.","pause_after":true}]}]}}]},{"icon":"📚","title":"Find a shared idea","explain":"**Learn:** Synthesis connects information from more than one source into a fuller understanding. A shared topic is not enough: identify the relationship.\n\n**Original context:** Text A: ''Native bees visit flowers to gather nectar and pollen. Pollen may travel between flowers on their bodies.'' Text B: ''Many flowering plants can form seeds after pollen reaches the appropriate part of a flower. Some animals, including bees, can carry pollen.''","example":"**Teacher model:** Both texts discuss movement of pollen involving bees. Text A describes the movement; Text B explains why it matters.\n\n**Guided example:** **Read two mini-texts.** Text A: ''Trees provide branches where some birds build nests.'' Text B: ''Bird nests can protect eggs and young from some weather conditions.'' State both main ideas, their shared idea (bird nests), and create a synthesis: ''Some birds build nests in trees, where the nests can shelter eggs and young.'' Explain why neither text claims every nest is in a tree.\n\n**CHECK:** Explain why this method is sound.","notice":"Synthesis connects information from more than one source into a fuller understanding. A shared topic is not enough: identify the relationship.","check":{"question":"What does Text B help explain?","options":["How pollen transfer may support seeds","Why bees have six legs","How tall every tree is","Where all hives are"],"correct_index":0,"explanation":"How pollen transfer may support seeds. Both texts discuss movement of pollen involving bees. Text A describes the movement; Text B explains why it matters."}},{"icon":"✏️","title":"Combine facts in your own words","explain":"**Learn:** Use a sentence that accurately draws on both texts without copying whole passages or claiming more than they say.\n\n**Original context:** Text A: ''Native bees visit flowers to gather nectar and pollen. Pollen may travel between flowers on their bodies.'' Text B: ''Many flowering plants can form seeds after pollen reaches the appropriate part of a flower. Some animals, including bees, can carry pollen.''","example":"**Teacher model:** ''Bees can carry pollen as they visit flowers, and this transfer can help some plants produce seeds.'' Each part comes from a different source.\n\n**Guided example:** **Read two mini-texts.** Text A: ''Trees provide branches where some birds build nests.'' Text B: ''Bird nests can protect eggs and young from some weather conditions.'' State both main ideas, their shared idea (bird nests), and create a synthesis: ''Some birds build nests in trees, where the nests can shelter eggs and young.'' Explain why neither text claims every nest is in a tree.\n\n**CHECK:** Explain why this method is sound.","notice":"Use a sentence that accurately draws on both texts without copying whole passages or claiming more than they say.","check":{"question":"What is synthesis?","options":["Connecting ideas from multiple sources","Copying one source repeatedly","Ignoring one text","Inventing a third unrelated story"],"correct_index":0,"explanation":"Connecting ideas from multiple sources. ''Bees can carry pollen as they visit flowers, and this transfer can help some plants produce seeds.'' Each part comes from a different source."}},{"icon":"✅","title":"Note limits and source contributions","explain":"**Learn:** Distinguish what is supported by either text from overgeneralisations. Explain which source supports each fact.\n\n**Original context:** Text A: ''Native bees visit flowers to gather nectar and pollen. Pollen may travel between flowers on their bodies.'' Text B: ''Many flowering plants can form seeds after pollen reaches the appropriate part of a flower. Some animals, including bees, can carry pollen.''","example":"**Teacher model:** Neither text proves every plant needs bees. Text A supports the bee behaviour, and Text B supports the possibility of seed production after pollen transfer.\n\n**Guided example:** **Read two mini-texts.** Text A: ''Trees provide branches where some birds build nests.'' Text B: ''Bird nests can protect eggs and young from some weather conditions.'' State both main ideas, their shared idea (bird nests), and create a synthesis: ''Some birds build nests in trees, where the nests can shelter eggs and young.'' Explain why neither text claims every nest is in a tree.\n\n**CHECK:** Explain why this method is sound.","notice":"Distinguish what is supported by either text from overgeneralisations. Explain which source supports each fact.","check":{"question":"Which statement uses both texts accurately?","options":["Bees may move pollen, helping some plants make seeds.","All plants need bees.","Bees make every seed.","Flowers do not need pollen."],"correct_index":0,"explanation":"Bees may move pollen, helping some plants make seeds.. Neither text proves every plant needs bees. Text A supports the bee behaviour, and Text B supports the possibility of seed production after pollen transfer."}}],"worked_example":"## Model the method\n\nText A: ''Native bees visit flowers to gather nectar and pollen. Pollen may travel between flowers on their bodies.'' Text B: ''Many flowering plants can form seeds after pollen reaches the appropriate part of a flower. Some animals, including bees, can carry pollen.''\n\n**1. Identify each text''s main idea:** Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds.\n\n**2. Find a shared idea:** Both texts discuss movement of pollen involving bees. Text A describes the movement; Text B explains why it matters.\n\n**3. Combine facts in your own words:** ''Bees can carry pollen as they visit flowers, and this transfer can help some plants produce seeds.'' Each part comes from a different source.\n\n**4. Note limits and source contributions:** Neither text proves every plant needs bees. Text A supports the bee behaviour, and Text B supports the possibility of seed production after pollen transfer.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 570 175\"><rect width=\"570\" height=\"175\" rx=\"10\" fill=\"#f2f8f4\"/><text x=\"14\" y=\"30\" font-family=\"Arial\" font-size=\"18\">Two Texts, One Explanation: Synthesise Information</text><rect x=\"9\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"16\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Identify each tex</text><rect x=\"151\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"158\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Find a shared ide</text><rect x=\"293\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#deeee4\"/><text x=\"300\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Combine facts in </text><rect x=\"435\" y=\"65\" width=\"132\" height=\"91\" rx=\"8\" fill=\"#e5ebfa\"/><text x=\"442\" y=\"112\" font-size=\"12\" font-family=\"Arial\">Note limits and s</text></svg>","alt":"Four key stages for Two Texts, One Explanation: Synthesise Information","caption":"Use the worked lesson examples with these stages."}],"guided_practice":"**Read two mini-texts.** Text A: ''Trees provide branches where some birds build nests.'' Text B: ''Bird nests can protect eggs and young from some weather conditions.'' State both main ideas, their shared idea (bird nests), and create a synthesis: ''Some birds build nests in trees, where the nests can shelter eggs and young.'' Explain why neither text claims every nest is in a tree.","independent_task":"**Independent two-source synthesis.** Text 1: ''Earthworms make tunnels as they move through soil. These tunnels can allow water and air to enter.'' Text 2: ''Many gardeners value soil that lets air and water move. Healthy soil conditions support plant roots.'' Write a separate one-sentence summary for each, then a 3–4 sentence synthesis showing the relationship between earthworm tunnels and garden soil. Label which text supports two of your facts. Identify one tempting but unsupported universal claim.","response_prompt":"**Independent two-source synthesis.** Text 1: ''Earthworms make tunnels as they move through soil. These tunnels can allow water and air to enter.'' Text 2: ''Many gardeners value soil that lets air and water move. Healthy soil conditions support plant roots.'' Write a separate one-sentence summary for each, then a 3–4 sentence synthesis showing the relationship between earthworm tunnels and garden soil. Label which text supports two of your facts. Identify one tempting but unsupported universal claim.","quiz":[{"type":"multiple_choice","question":"What does Text A describe?","options":["Bees moving pollen as they visit flowers","All plant seeds are made by bees","Only birds pollinate","Every flower grows underwater"],"correct_index":0,"explanation":"Bees moving pollen as they visit flowers. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"multiple_choice","question":"What does Text B help explain?","options":["How pollen transfer may support seeds","Why bees have six legs","How tall every tree is","Where all hives are"],"correct_index":0,"explanation":"How pollen transfer may support seeds. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"multiple_choice","question":"What is synthesis?","options":["Connecting ideas from multiple sources","Copying one source repeatedly","Ignoring one text","Inventing a third unrelated story"],"correct_index":0,"explanation":"Connecting ideas from multiple sources. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"multiple_choice","question":"Which statement uses both texts accurately?","options":["Bees may move pollen, helping some plants make seeds.","All plants need bees.","Bees make every seed.","Flowers do not need pollen."],"correct_index":0,"explanation":"Bees may move pollen, helping some plants make seeds.. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"multiple_choice","question":"Which is unsupported by both texts?","options":["Every plant requires bees.","Bees may visit flowers.","Pollen can move between flowers.","Pollen may assist seed production."],"correct_index":0,"explanation":"Every plant requires bees.. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"multiple_choice","question":"What comes before synthesising?","options":["Understanding each text separately","Picking the longest sentence","Removing source names","Writing a random opinion"],"correct_index":0,"explanation":"Understanding each text separately. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"multiple_choice","question":"What does Text A support?","options":["Bees visit flowers and may carry pollen","Every seed needs a bee","All bees live in hives","All flowers share identical pollen"],"correct_index":0,"explanation":"Bees visit flowers and may carry pollen. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"multiple_choice","question":"Why label source contributions?","options":["Show which text supports each claim","Add unrelated decoration","Avoid checking accuracy","Prove all claims are facts"],"correct_index":0,"explanation":"Show which text supports each claim. Text A explains what native bees collect and how pollen may be moved. Text B explains how pollen transfer can help plants make seeds."},{"type":"short_answer","question":"Complete the independent two texts, one explanation: synthesise information task.","sample_answer":"Text 1: Earthworm tunnels can help air and water move into soil. Text 2: Soil that allows air and water movement can support plant roots. Synthesis: Earthworms move through soil and form tunnels. According to Text 1, those tunnels can let air and water enter. Text 2 explains why this may be useful: air and water movement can support roots. Together, the texts show a possible way earthworms contribute to garden soil conditions.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."},{"type":"short_answer","question":"Explain an important check or limitation in two texts, one explanation: synthesise information.","sample_answer":"An unsupported claim is ''every garden plant needs earthworms to survive''. Neither text proves this. My synthesis connects tunnel effects from Text 1 with soil needs from Text 2 without claiming a universal rule.","marking_guide":"Check accurate answers, all task components and supporting reasons.","explanation":"The response should show the method and explanation."}],"parent_notes":"Parent: Have the child independently attempt the challenge and explain their approach before using these answers.\n\nParent: Written answer model 1. Text 1: Earthworm tunnels can help air and water move into soil. Text 2: Soil that allows air and water movement can support plant roots. Synthesis: Earthworms move through soil and form tunnels. According to Text 1, those tunnels can let air and water enter. Text 2 explains why this may be useful: air and water movement can support roots. Together, the texts show a possible way earthworms contribute to garden soil conditions.\n\nParent: Written answer model 2. An unsupported claim is ''every garden plant needs earthworms to survive''. Neither text proves this. My synthesis connects tunnel effects from Text 1 with soil needs from Text 2 without claiming a universal rule.\n\nParent: Retain original learning evidence and check NESA mapping separately.","evidence_instructions":"Save guided practice, independent work, a correction and both written assessments.","offline_alternative":"Complete the exercises on paper and retain a scan, photo or typed answer.","extension":"Design a new two texts, one explanation: synthesise information example and demonstrate your checking method.","stage_hints":{"accept":["Review the Two Texts, One Explanation: Synthesise Information prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach0":["Review the Identify each text''s main idea prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach1":["Review the Find a shared idea prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach2":["Review the Combine facts in your own words prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"teach3":["Review the Note limits and source contributions prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"learn":["Review the Two Texts, One Explanation: Synthesise Information prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"guided":["Review the Two Texts, One Explanation: Synthesise Information prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"write":["Review the Two Texts, One Explanation: Synthesise Information prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"quiz":["Review the Two Texts, One Explanation: Synthesise Information prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."],"submit":["Review the Two Texts, One Explanation: Synthesise Information prompt.","Return to the original number groups or source statements.","Use the evidence to check and explain your solution."]}}') WHERE seed_key='s2-eng-y3-w10-l1';
